import HeroSectionV6 from "./hero-section-v6"

export default function Page() {
  return <HeroSectionV6 />
}

import BrandsSectionV5 from "../brands-section-v5/brands-section-v5"

import { HeroV6Root } from "./components/hero-v6-root"

import "./styles/hero-section-v6.css"

export default function HeroSectionV6() {
  return (
    <>
      <section className="hero-v6 pb-0 pt-10 md:pb-0 md:pt-14 lg:pb-0 lg:pt-16">
        <HeroV6Root />
      </section>
      <BrandsSectionV5 animated />
    </>
  )
}

import Image from "next/image"

export function HeroV6Image() {
  return (
    <Image
      src="/images/blocks/hero-section-v6/hero-section-v6.jpg"
      alt="Payroll operations dashboard preview"
      fill
      className="object-contain"
      sizes="(max-width: 640px) 100vw, (max-width: 1024px) 95vw, 1280px"
      priority
    />
  )
}

import { forwardRef } from "react"
import { PerlinNoise } from "@paper-design/shaders-react"

const ShaderImageBg = forwardRef<HTMLDivElement>(function ShaderImageBg(_, ref) {
  return (
    <div ref={ref} className="hero-v6-noise-frame" aria-hidden>
      <PerlinNoise
        width={1280}
        height={720}
        colorBack="#ffffff"
        colorFront="#262626"
        proportion={0.65}
        softness={0.35}
        octaveCount={6}
        persistence={1}
        lacunarity={2.55}
        speed={0.02}
        scale={4}
      />
    </div>
  )
})

export default ShaderImageBg

.hero-v6 {
  --hero-v6-ease-out: cubic-bezier(0.22, 1, 0.36, 1);
}

.hero-v6-media-shell {
  --frame-pad: clamp(0.7rem, 2.2vw, 1.7rem);
  position: relative;
  aspect-ratio: 16 / 9;
  width: 100%;
  margin-top: clamp(1rem, 1.5vw, 1.5rem);
  padding: var(--frame-pad);
  background: #2b2f3a;
}

.hero-v6-noise-frame {
  position: absolute;
  inset: 0;
  border-radius: 0;
  overflow: hidden;
  opacity: 0.9;
}

.hero-v6-noise-frame canvas {
  width: 100% !important;
  height: 100% !important;
  display: block;
}

.hero-v6-noise-frame::before {
  content: "";
  position: absolute;
  inset: 0;
  background-image:
    repeating-linear-gradient(
      45deg,
      rgba(255, 255, 255, 0.07) 0 1px,
      transparent 1px 4px
    ),
    repeating-linear-gradient(
      -45deg,
      rgba(0, 0, 0, 0.12) 0 1px,
      transparent 1px 5px
    );
  pointer-events: none;
}

.hero-v6-noise-frame::after {
  content: "";
  position: absolute;
  inset: 0;
  background: linear-gradient(
    135deg,
    rgba(255, 255, 255, 0.12),
    transparent 42%,
    rgba(15, 23, 42, 0.22)
  );
  pointer-events: none;
}

.hero-v6-media-inner {
  position: absolute;
  inset: var(--frame-pad);
  z-index: 1;
  overflow: hidden;
  border: 1px solid rgba(15, 23, 42, 0.22);
  background: #f5f5f5;
}

@media (max-width: 640px) {
  .hero-v6-media-shell {
    --frame-pad: 0.65rem;
    margin-top: 0.85rem;
  }
}

@media (prefers-reduced-motion: no-preference) {
  .hero-v6 [data-hero-v6-reveal],
  .hero-v6 [data-hero-v6-word],
  .hero-v6 .hero-v6-media-shell,
  .hero-v6 .hero-v6-noise-frame {
    opacity: 0;
    will-change: transform, opacity;
  }
}

@media (prefers-reduced-motion: reduce) {
  .hero-v6 [data-hero-v6-reveal],
  .hero-v6 [data-hero-v6-word],
  .hero-v6 .hero-v6-media-shell,
  .hero-v6 .hero-v6-noise-frame {
    opacity: 1;
    transform: none;
    filter: none;
  }
}
